#!/usr/bin/env python3
"""
Patch 23: a guided tour (one exemplar per case family, freezing on a computed frame) and a
cross-fading case switcher. Frontend only; wraps the existing UI without changing card logic.

First install the tour library:  (cd frontend && npm install driver.js@1.8.0)
Then run this from the repository root with patches 05-22 applied. Every file replaced is
checked against the exact version this patch was written for; nothing is written unless all
of it matches. Safe to re-run.
"""
import hashlib, json, os, sys
def abort(msg):
    sys.exit(f"ABORT: {msg}. No files were written.")
if "driver.js" not in json.load(open("frontend/package.json")).get("dependencies", {}):
    abort("driver.js is not installed yet - run: (cd frontend && npm install driver.js@1.8.0)")
